package com.codegym.inotes.strategy;
import com.codegym.inotes.model.Note; import java.io.IOException; import java.sql.*; import java.util.*;
public class NoteDBStrategy implements NoteStrategy { private final String url,user,password; public NoteDBStrategy(String url,String user,String password){this.url=url;this.user=user;this.password=password;} private Connection connect()throws SQLException{return DriverManager.getConnection(url,user,password);} private Note map(ResultSet r)throws SQLException{return new Note(r.getInt("id"),r.getString("title"),r.getString("content"),r.getInt("type_id"));} public void save(Note n)throws IOException{try(Connection c=connect();PreparedStatement p=n.getId()==0?c.prepareStatement("INSERT INTO notes(title,content,type_id) VALUES(?,?,?)",Statement.RETURN_GENERATED_KEYS):c.prepareStatement("UPDATE notes SET title=?,content=?,type_id=? WHERE id=?")){p.setString(1,n.getTitle());p.setString(2,n.getContent());p.setInt(3,n.getTypeId());if(n.getId()!=0)p.setInt(4,n.getId());p.executeUpdate();}catch(SQLException e){throw new IOException(e);}} public void delete(int id)throws IOException{try(Connection c=connect();PreparedStatement p=c.prepareStatement("DELETE FROM notes WHERE id=?")){p.setInt(1,id);p.executeUpdate();}catch(SQLException e){throw new IOException(e);}} public List<Note> findAll()throws IOException{return search("");} public List<Note> search(String k)throws IOException{List<Note> out=new ArrayList<>();try(Connection c=connect();PreparedStatement p=c.prepareStatement("SELECT id,title,content,type_id FROM notes WHERE title LIKE ? OR content LIKE ? ORDER BY id DESC")){String q="%"+(k==null?"":k)+"%";p.setString(1,q);p.setString(2,q);try(ResultSet r=p.executeQuery()){while(r.next())out.add(map(r));}}catch(SQLException e){throw new IOException(e);}return out;} }
